ks\n  certificate_url VARCHAR(500) NULL,\n  remarks TEXT NULL,\n  \n  -- Audit fields\n  created_by INT NULL,\n  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,\n  \n  -- Foreign Keys & Indexes\n  INDEX idx_contact_qual (contact_id),\n  INDEX idx_business_qual (business_id),\n  FOREIGN KEY (contact_id) REFERENCES contacts(id) ON DELETE CASCADE,\n  FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE CASCADE,\n  FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;','delivered','2026-11-14 10:53:45','2026-11-14 10:53:42'),(9,1,39,70,'sess_u5q6q4mc','inbound','3EB06DA9393715EB2FE60F','-- 1. Create Qualifications Table\nCREATE TABLE IF NOT EXISTS contact_qualifications (\n  id INT AUTO_INCREMENT PRIMARY KEY,\n  contact_id INT NOT NULL,\n  business_id INT NOT NULL,\n  degree_level VARCHAR(100) NOT NULL,\n  degree_title VARCHAR(255) NOT NULL,\n  field_of_study VARCHAR(255) NULL,\n  institution_name VARCHAR(255) NOT NULL,\n  board_or_university VARCHAR(255) NULL,\n  passing_year VARCHAR(20) NULL,\n  grading_system VARCHAR(50) DEFAULT \'Percentage\',\n  score VARCHAR(50) NULL,\n  certificate_url VARCHAR(500) NULL,\n  remarks TEXT NULL,\n  created_by INT NULL,\n  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,\n  FOREIGN KEY (contact_id) REFERENCES contacts(id) ON DELETE CASCADE,\n  FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE CASCADE,\n  FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;\n\n-- 2. Create Work Experiences Table\nCREATE TABLE IF NOT EXISTS contact_work_experiences (\n  id INT AUTO_INCREMENT PRIMARY KEY,\n  contact_id INT NOT NULL,\n  business_id INT NOT NULL,\n  company_name VARCHAR(255) NOT NULL,\n  job_title VARCHAR(